steps.script:
await $wait('#newSimpleSearch');
await $type('#newSimpleSearch', __input__.keyword);
await new Promise(r => setTimeout(r, 500));
await $click("sds-search form.usa-search button[type='submit']");
return { done: true };

await new Promise(r => setTimeout(r, 3000));
const hasResults = await $exists('sds-search-result-list app-opportunity-result, sds-search-result-list app-exclusion-result', 3000);
const noResults = await $exists('.card-title', 1000);
if (hasResults) return { done: true };
if (noResults) return { done: true, empty: true };
return { done: false };

const target = Number(__input__.page || 1);
if (target <= 1) return { done: true, page: 1 };

const state = (__lastResult__ && typeof __lastResult__.page === 'number') ? __lastResult__ : { page: 1, triedJump: false };

// Attempt 1: direct jump via the pagination input (type + blur to trigger change)
if (!state.triedJump) {
  try {
    await $type('#bottomPagination-currentPage', String(target));
    await new Promise(r => setTimeout(r, 400));
    // blur the input so the change event fires (click a neutral heading)
    await $click('#header-508');
    await new Promise(r => setTimeout(r, 3000));
    const v = String(await $extract('#bottomPagination-currentPage', 'value', 3000)).trim();
    if (v === String(target)) return { done: true, page: target };
  } catch (e) { /* fall through to stepping */ }
  state.triedJump = true;
  return { done: false, page: state.page, triedJump: true };
}

// Fallback: step forward one page at a time, tracking the page number ourselves
const hasNext = await $exists('#bottomPagination-nextPage', 2000);
if (!hasNext) return { done: true, page: state.page, exhausted: true };
await $click('#bottomPagination-nextPage');
await new Promise(r => setTimeout(r, 3000));
state.page = state.page + 1;
if (state.page >= target) return { done: true, page: target };
return { done: false, page: state.page, triedJump: true };

await new Promise(r => setTimeout(r, 3000));

// Don't gate on the pagination input's value (it reads 0/unreliably in this DOM).
// Instead verify the results list is rendered and stable, then collect links.
const hasResults = await $exists('sds-search-result-list app-opportunity-result, sds-search-result-list app-exclusion-result', 5000);
if (!hasResults) {
  // If a "no results" card is shown, that's a deterministic empty — report done.
  const noResults = await $exists('.card-title', 2000);
  if (noResults) return { done: true, items: [], index: 0, results: [], empty: true };
  return { done: false };
}

// Wait for content stability so we don't grab links mid-render
await $waitForStable('sds-search-result-list', { maxMs: 15000 });

let links = await $list("sds-search-result-list a.usa-link[href*='/view']");
let items = links.map(l => ({ href: l.href, text: (l.textContent || '').trim() })).filter(i => i.href);

// Fallback selector: title links inside each result item
if (items.length === 0) {
  links = await $list('app-opportunity-result h3 a');
  items = links.map(l => ({ href: l.href, text: (l.textContent || '').trim() })).filter(i => i.href);
}

return { done: true, items, index: 0, results: [], page: __input__.page || 1 };

const state = __lastResult__;
if (!state || !state.items || state.items.length === 0) return { done: true, contracts: [] };
if (state.index >= state.items.length) {
  return { done: true, contracts: state.results };
}
const item = state.items[state.index];
let detail = { title: item.text, url: item.href, detailHtml: '' };
try {
  detail = await $openTab(item.href, `
    await $wait('app-opps-display h1.card-title', 20000);
    await new Promise(r => setTimeout(r, 1500));
    const g = async (sel) => { try { return (await $extract(sel, null, 800) || '').trim(); } catch(e) { return ''; } };
    const title = await g('h1.card-title');
    const status = await g('.sds-tag--status');
    const noticeId = await g('h5[aria-describedby="notice-id"]');
    const relatedNotice = await g('h5[aria-describedby="related-notice"]');
    const contractType = await g('h5[aria-describedby="contract-type"]');
    const contractLineNumber = await g('h5[aria-describedby="contract-line-number"]');
    const inactiveDates = await g('h5[aria-describedby="inactive-dates"]');
    const inactivePolicy = await g('h5[aria-describedby="inactive-policy"]');
    const responseDate = await g('h5[aria-describedby="date-offers-date"]');
    const publishedDate = await g('h5[aria-describedby="published-date"]');
    const department = await g('h5[aria-describedby="dept-agency"]');
    const subTier = await g('h5[aria-describedby="sub-tier"]');
    const office = await g('h5[aria-describedby="office"]');
    const awardDate = await g('app-award-details h5[aria-describedby="title-one-row"]');
    const awardNumber = await g('app-award-details .grid-col-3:nth-of-type(2) h5[aria-describedby="title-one-row"]');
    const awardedAddress = await g('h5[aria-describedby="address"]');
    const awardedUEI = await g('h5[aria-describedby="title-two-row"]');
    const awardedName = await g('app-award-details .grid-col-fill h5[aria-describedby="title-one-row"]');
    const setAside = await g('h5[aria-describedby="set-aside"]');
    const psc = await g('h5[aria-describedby="psc"]');
    const naics = await g('h5[aria-describedby="naics"]');
    const placeOfPerformance = await g('#poc ~ .grid-row .sds-field__value');
    const description = await g('app-solicitation-details #desc .value-new-line');
    const pocName = await g('h5.contact-title-2');
    const pocEmail = await g('h6[aria-describedby="email"]');
    const pocPhone = await g('h6[aria-describedby="phone"]');
    let detailHtml = '';
    try { detailHtml = await $extract('app-opps-display', 'outerHTML', 3000); } catch(e) {}
    return { title, status, noticeId, relatedNotice, contractType, contractLineNumber, inactiveDates, inactivePolicy, responseDate, publishedDate, department, subTier, office, awardDate, awardNumber, awardedAddress, awardedUEI, awardedName, setAside, psc, naics, placeOfPerformance, description, pocName, pocEmail, pocPhone, detailHtml };
  `);
} catch (e) {
  detail.error = String(e);
}
detail.url = item.href;
if (!detail.title) detail.title = item.text;
state.results.push(detail);
state.index = state.index + 1;
return { done: false, items: state.items, index: state.index, results: state.results };
